"""
    This function returns the directory + file_name
    of the inputs.

    In general, it is used to do mosaic with many
    geotiff files.

    :param directory:       String
    :param file_names:      String
    :return:                list
                            It returns a list with
                            Strings. Each string
                            has the merge of
                            the directory and file
                            name.
    """
def set_tif_names(directory: Any, file_names: Any) -> object {
    tif_names = [];
    for i in file_names {
        tif_names.append((directory + i + '.tif'));
    }
    return tif_names;
}

test_blocks:
test "t0" {
    assert (set_tif_names('directory/', ['file']) == ['directory/file.tif']);;
}

test "t1" {
    assert (
        set_tif_names('directory', ['file1', 'file2'])
        == ['directoryfile1.tif', 'directoryfile2.tif']
    );;
}

test "t2" {
    assert (
        set_tif_names('data/', ['sample_tif_1', 'sample_tif_2'])
        == ['data/sample_tif_1.tif', 'data/sample_tif_2.tif']
    );;
}

test "t3" {
    assert (
        set_tif_names('directory/', ['file_1', 'file_2'])
        == ['directory/file_1.tif', 'directory/file_2.tif']
    );;
}

test "t4" {
    assert (
        set_tif_names('data/tif/', ['1', '2', '3'])
        == ['data/tif/1.tif', 'data/tif/2.tif', 'data/tif/3.tif']
    );;
}

