        == [
            'C:/Users/User/Desktop/FES_Compensation/Mosaic_FES_data/TIF/2020-09-06_16-10-05_280000_9900000.tif',
            'C:/Users/User/Desktop/FES_Compensation/Mosaic_FES_data/TIF/2020-09-06_16-10-15_320000_9900000.tif',
            'C:/Users/User/Desktop/FES_Compensation/Mosaic_FES_data/TIF/2020-09-06_16-10-24_320000_9900000.tif'
